  let PI = null, PN = -1;
  const paysOf = (id) => { const L = db.all('payments'); if (!PI || PN !== L.length) { PI = new Map(); PN = L.length; L.forEach((p) => { if (!PI.has(p.stay)) PI.set(p.stay, []); PI.get(p.stay).push(p); }); } return PI.get(id) || []; };
  const pay = (k) => H.odeme(k, paysOf(k.id), today());
  const yasEt = (s) => { const r = s.minor !== undefined ? s.minor : H.resitDegil(s, today()); return r ? badge('Reşit değil', 'warn') : ''; };
  const resitDegil = (s) => (s.minor !== undefined ? s.minor : H.resitDegil(s, today())); // nöbetçi rolünde sunucu doğum tarihi yerine bu bilgiyi verir
  const veliAcik = (s) => (s.veliAcik !== undefined ? s.veliAcik : H.veliPaylasir(s, today()));
  const iso2 = (d) => new Date(d).toISOString();
  const PAY = [{ value: 'havale', label: 'Havale / EFT' }, { value: 'kart', label: 'Kart' }, { value: 'nakit', label: 'Nakit' }];
  const yuvarla = (s) => String(s || '').replace(/\D/g, '').slice(-10);
  const nowHM = () => new Date().toTimeString().slice(0, 5);
  const geceKapali = () => S().gateOn && nowHM() >= (S().gateHour || '23:00');

  // ---------- Belgeler ----------
  const ayrilisMetni = () => { const r = S().rejim === 'meb' ? H.REJIM.meb : H.REJIM.gsb; return `${r.ad} rejiminde ayrılışta ücret, bağlı olduğunuz yönetmeliğe ve bu taahhütnameye göre hesaplanır. Kalan aylar için yüzde ${S().leavePct === '' || S().leavePct === undefined ? r.pct : S().leavePct} oranında kesinti yapılır, kalan tutar bir ay içinde iade edilir.`; };
