  const kimlik = (s) => ({ title: resitDegil(s) ? 'Öğrenci ve veli' : 'Öğrenci', name: s.name, lines: [s.phone, s.school, resitDegil(s) ? `Veli: ${s.guardian.name} · ${s.guardian.phone}` : ''] });
  const taahhutDoc = (k) => { const s = stu(k.student); return { title: 'Hizmet sunum taahhütnamesi', no: s.no, date: k.signedAt || nowIso(), party: kimlik(s), info: [['Dönem', term(k.term).name], ['Oda / yatak', `${room(k.room).no} / ${k.bed}`], ['Giriş', NS.date(k.from)], ['Çıkış', NS.date(k.to)]], lines: k.plan.map((t) => ({ name: t.label, qty: NS.date(t.due), total: t.amount })), totals: [['Dönem toplamı', sum(k.plan, (t) => t.amount), true], ['Depozito', k.deposit || 0]], note: doldur(S().taahhut, k), signatures: [{ label: 'Kurum' }, { label: resitDegil(s) ? 'Veli' : 'Öğrenci', ...(k.sign || {}) }] }; };
  const makbuzDoc = (k, p) => ({ title: p.amount < 0 ? 'İade makbuzu' : 'Tahsilat makbuzu', no: p.receipt, date: p.at, party: kimlik(stu(k.student)), info: [['Dönem', term(k.term).name], ['Tür', p.kind === 'depozito' ? 'Depozito' : p.kind === 'iade' ? 'İade' : 'Barınma ücreti'], ['Ödeme', p.type]], totals: [['Tutar', Math.abs(p.amount), true]] });
  const depoDoc = (k) => { const o = k.depoOut; return { title: 'Depozito hesap dökümü', no: stu(k.student).no, date: o.at, party: kimlik(stu(k.student)), lines: o.kesinti.map((x) => ({ name: x.reason, qty: 1, total: x.amount })), totals: [['Alınan', o.alinan], ['Kesinti', o.kes], ['İade', o.iade, true]], note: 'Kesintilerin her biri gerekçesiyle yazılmıştır. İtirazınızı kuruma yazılı iletebilirsiniz.' }; };
  const izinDoc = (l) => { const s = stu(l.student); return { title: 'İzin belgesi', no: s.no, date: l.created, party: kimlik(s), info: [['Başlangıç', NS.date(l.from)], ['Bitiş', NS.date(l.to)], ['Gideceği yer', l.dest], ['Veli teyidi', l.guardianOk ? 'Var' : 'Yok']], signatures: [{ label: 'Kurum' }, { label: 'Veli / öğrenci' }] }; };
  const kimlikDoc = (L) => ({ title: 'Kimlik bildirim hazırlık listesi', date: nowIso(), lines: L.map((x) => ({ name: `${x.s.name} · ${x.tur} · ${NS.date(x.gun)}`, qty: x.son ? NS.date(x.son) : '-', unit: 'son gün' })), note: 'Bu liste bildirim değildir. Bildirimi yetkili sistemden veya kolluğa yapın, sonra programda işaretleyin.' });
