  const UYARI = 'Örnek şablon. Bağlayıcı hukuki metin değildir; kullanmadan önce avukatınıza gösterin.';
  const T = (name, label, type = 'text') => ({ name, label, type });
  if (NS.forms) { NS.forms.FORMS.yurt = { coll: 'students', party: 'Öğrenci / veli', kinds: [
    { id: 'oda', label: 'Oda teslim tutanağı', sign: ['Kurum', 'Öğrenci'], uyari: UYARI, fields: [T('oda', 'Oda / yatak'), T('demirbas', 'Demirbaş ve oda durumu', 'textarea')], body: 'ÖRNEK ŞABLON. {{musteri}}, {{oda}} odasını aşağıdaki durumda teslim almıştır / teslim etmiştir: {{demirbas}}' },
    { id: 'riza', label: 'Veli bilgilendirme izni', sign: ['Kurum', 'Öğrenci'], uyari: UYARI, fields: [T('veli', 'Bilgi verilecek veli'), T('kapsam', 'Paylaşılacak bilgi (giriş-çıkış, ödeme)')], body: 'ÖRNEK ŞABLON. Reşit öğrenci {{musteri}}, {{kapsam}} bilgilerinin {{veli}} ile paylaşılmasını kabul eder. Bu izni dilediği zaman geri alabilir.' },
  ] }; NS.forms.FORMS.yurt.kinds.forEach((k) => NS.forms.tanit('yurt', k)); }
  if (NS.notify && NS.notify.define) NS.notify.define('yurt', [{ key: 'izin', label: 'Yeni izin talebi', desc: 'Öğrenci veya veli portaldan izin istediğinde', sound: 'marimba', coll: 'leaves', when: (l) => l.status === 'bekliyor', title: () => 'Yeni izin talebi', href: '#/izinler' }, { key: 'ariza', label: 'Yeni arıza bildirimi', desc: 'Öğrenci portaldan arıza bildirdiğinde', sound: 'ding', coll: 'tickets', when: (t) => t.src === 'ogrenci', title: () => 'Yeni arıza bildirimi', href: '#/ariza' }]);
  const veliSms = (s, text) => { if (!veliAcik(s) || !s.guardian.phone) return null; return NS.smsLog(db, { to: s.guardian.phone, name: s.guardian.name, text: `${S().bizName}: ${text}`, kind: 'veli' }, true).result.then((r) => toast(NS.smsText(r, 'Veli bildirimi'), NS.smsTone(r))); };

  // ---------- Kayıt ----------
  const yatakOpt = (st) => db.all('rooms', (r) => r.status !== 'kapali' && (!st || !r.gender || r.gender === 'karma' || r.gender === st)).flatMap((r) => Array.from({ length: Number(r.beds) || 0 }, (_, b) => ({ r, b: b + 1 })).filter((x) => !H.yatakDolu(db.all('stays'), r.id, x.b))).slice(0, 400).map((x) => ({ value: `${x.r.id}|${x.b}`, label: `${x.r.no} · yatak ${x.b}` }));
  const STU_F = (o = {}) => [{ name: 'name', label: 'Ad soyad', required: true, value: o.name }, { name: 'birth', label: 'Doğum tarihi', type: 'date', required: true, value: o.birth, hint: 'Reşit olma durumu ve veli paylaşımı buna göre belirlenir' }, { name: 'gender', label: 'Cinsiyet', type: 'select', options: [{ value: 'K', label: 'Kadın' }, { value: 'E', label: 'Erkek' }], value: o.gender }, { name: 'phone', label: 'Telefon', type: 'tel', required: true, value: o.phone }, { name: 'school', label: 'Okul', value: o.school }, { name: 'dept', label: 'Bölüm / sınıf', value: o.dept }, { type: 'section', label: 'Veli' }, { name: 'gName', label: 'Veli adı', required: true, value: (o.guardian || {}).name }, { name: 'gRel', label: 'Yakınlık', value: (o.guardian || {}).rel }, { name: 'gPhone', label: 'Veli telefonu', type: 'tel', required: true, value: (o.guardian || {}).phone }, { type: 'section', label: 'Acil durum' }, { name: 'emergency', label: 'Acil durum telefonu', value: o.emergency }, { name: 'acilNot', label: 'Görevlinin bilmesi gereken kısa not', value: o.acilNot, hint: 'Yalnızca acil durumda gereken bilgi' }, { name: 'health', label: 'Sağlık bilgisi (yönetici görür)', type: 'textarea', full: true, value: o.health }];
